// ElevenLabs sends this after the call ends (post-call webhook).
// Field names below follow ElevenLabs' convai post-call payload as of late 2025 -
// double check against https://elevenlabs.io/docs/conversational-ai/workflows/post-call-webhooks if the fields come through empty.
const payload = $input.first().json.body || $input.first().json;
const data = payload.data || payload;
const analysis = data.analysis || {};
const criteria = analysis.evaluation_criteria_results || {};
const collected = analysis.data_collection_results || {};

function val(obj, key) {
  const v = obj[key];
  if (v === undefined) return null;
  return (v && typeof v === "object" && "value" in v) ? v.value : v;
}

const review = {
  call_id: data.conversation_id || payload.conversation_id || null,
  agent_id: data.agent_id || null,
  call_successful: analysis.call_successful || "unknown",
  issue_resolved: val(criteria, "resolved"),
  correct_process_followed: val(criteria, "process_followed"),
  follow_up_required: val(criteria, "follow_up_required"),
  employee_id: val(collected, "employee_id"),
  issue_category: val(collected, "issue_category"),
  ticket_id: val(collected, "ticket_id"),
  summary: analysis.transcript_summary || null,
  generated_at: new Date().toISOString()
};

return [{ json: review }];
